import React from 'react';
import { FormattedMessage, useIntl } from 'react-intl';

import Breakpoints from '@dynatrace/strato-design-tokens/breakpoints-js';
import {
  ChevronLeftSmallIcon,
  ChevronRightSmallIcon,
} from '@dynatrace/strato-icons';

import { Button } from '../../../../buttons/button/Button.js';
import { useBreakpoint } from '../../../../core/hooks/useBreakpoint.js';
import { _useId } from '../../../../core/hooks/useId.js';
import { Label } from '../../../../forms/forms-core/components/label/Label.js';
import { SelectV2 } from '../../../../forms/selectv2/Select.js';
import { Flex } from '../../../../layouts-core/flex/Flex.js';
import { Text } from '../../../../typography/Text.js';
import { dataTableMessages } from '../../../DataTable/messages.js';
import { useDataTableV2 } from '../../contexts/DataTableV2Context.js';
/**
 * DatatTableV2 internal pagination component that is actually rendering the pagination.
 * @internal
 */
interface _DataTableV2PaginationInternalProps {
  /** Whether the previous page is available (if not, the go to previous page button should be disabled).	*/
  enablePreviousPage?: boolean;
  /** Whether the next page is available (if not, the go to next page button should be disabled). */
  enableNextPage?: boolean;
  /** Number of rows per page  */
  pageSize: number;
  /** Handler that is called when the page size changes. */
  onPageSizeChange: (newPageSize: number) => void;

  /** Number that represents the number of available pages. Will be -1 for server side pagination.  */
  pageCount: number;
  /** Current page index in a controlled scenario. */
  pageIndex: number;
  /** Called when the page index changes. Provides the changed page index along with the underlying trigger. */
  onPageIndexChange: (newPageIndex: number) => void;
  /** Defines the available numbers for the pageSize select. */
  pageSizeOptions: number[];
}

/**
 * Internal component that actually renders the pagination.
 * @public
 */
export function _DataTableV2PaginationInternal(
  props: _DataTableV2PaginationInternalProps,
) {
  const table = useDataTableV2();
  const intl = useIntl();

  const pageSizeSelectId = _useId();
  const pageIndexSelectId = _useId();

  const isServerSidePaginated =
    props.enableNextPage !== undefined ||
    props.enablePreviousPage !== undefined;

  // An array of zero-based index integers corresponding to available pages in the table
  const pageCountArray = Array.from({ length: props.pageCount }, (_, i) => i);

  const smallScreen = useBreakpoint(`(max-width: ${Breakpoints.Max.Mobile}px)`);

  return (
    <Flex
      data-testid={props['data-testid']}
      justifyContent="space-between"
      paddingTop={8}
      role="navigation"
      flexWrap="wrap"
    >
      <Flex alignItems="center">
        <SelectV2
          id={pageSizeSelectId}
          value={props.pageSize}
          required
          onChange={(newPageSize: number) => {
            props.onPageSizeChange?.(newPageSize);
          }}
          aria-label={intl.formatMessage(dataTableMessages.selectPageSize)}
        >
          <SelectV2.Content>
            {props.pageSizeOptions.map((pageSize) => (
              <SelectV2.Option
                key={`${pageSize}`}
                id={pageSize}
                value={pageSize}
              >
                {`${pageSize}`}
              </SelectV2.Option>
            ))}
          </SelectV2.Content>
        </SelectV2>
        <Label htmlFor={pageSizeSelectId}>
          <Text as="span" style={{ whiteSpace: 'nowrap' }}>
            <FormattedMessage
              description="Text to display when choosing the number of rows per page."
              defaultMessage="rows per page"
              id="lu2hmVHtfcnVRPtz"
            />
          </Text>
        </Label>
      </Flex>

      <Flex gap={16}>
        {!isServerSidePaginated && (
          <Flex flexWrap="nowrap" alignItems="center">
            <Label htmlFor={pageIndexSelectId}>
              <Text as="p">
                <FormattedMessage
                  description="Label for page selection dropdown."
                  defaultMessage="Page"
                  id="LCNiBr0aBntMq391"
                />
              </Text>
            </Label>
            <SelectV2
              id={pageIndexSelectId}
              value={props.pageIndex}
              onChange={props.onPageIndexChange}
              aria-label={intl.formatMessage(dataTableMessages.selectPage)}
            >
              <SelectV2.Content>
                {pageCountArray.length === 0 ? (
                  <SelectV2.Option key={'pageIndex-0'} id={0} value={0}>
                    {0}
                  </SelectV2.Option>
                ) : (
                  pageCountArray.map((pageIndex) => (
                    <SelectV2.Option
                      key={`pageIndex-${pageIndex}`}
                      id={pageIndex}
                      value={pageIndex}
                    >
                      {pageIndex + 1}
                    </SelectV2.Option>
                  ))
                )}
              </SelectV2.Content>
            </SelectV2>
            {!smallScreen && (
              <Label htmlFor={pageIndexSelectId}>
                <Text
                  as="span"
                  textStyle="base"
                  style={{ whiteSpace: 'nowrap' }}
                >
                  <FormattedMessage
                    description="Text displaying the amount of pages."
                    defaultMessage="of {totalPages}"
                    id="HzhWa5UT4EGJIstf"
                    values={{ totalPages: props.pageCount }}
                  />
                </Text>
              </Label>
            )}
          </Flex>
        )}
        {(!smallScreen || isServerSidePaginated) && (
          <Flex gap={2}>
            <Button
              onClick={() => {
                const nextPageIndex = Math.max(0, props.pageIndex - 1);
                props.onPageIndexChange(nextPageIndex);
              }}
              disabled={
                table.options.manualPagination
                  ? !table.getState().pagination.enablePreviousPage
                  : !table.getCanPreviousPage()
              }
              aria-label={intl.formatMessage({
                defaultMessage: 'Go to previous page.',
                id: 'VoqQWp9yEM0QM8eF',
                description: 'Aria label to add to the `previous` button',
              })}
              variant="default"
            >
              <Button.Prefix>
                <ChevronLeftSmallIcon />
              </Button.Prefix>
            </Button>
            <Button
              onClick={() => {
                props.onPageIndexChange(props.pageIndex + 1);
              }}
              disabled={
                table.options.manualPagination
                  ? !table.getState().pagination.enableNextPage
                  : !table.getCanNextPage()
              }
              aria-label={intl.formatMessage({
                defaultMessage: 'Go to next page.',
                id: 'KAAzM9PVtiJno9ks',
                description: 'Aria label to add to the `next` button',
              })}
              variant="default"
            >
              <Button.Prefix>
                <ChevronRightSmallIcon />
              </Button.Prefix>
            </Button>
          </Flex>
        )}
      </Flex>
    </Flex>
  );
}
